priest: { level: 6, shield: 0.12, name: 'Слово силы: Щит', icon: '🛡️' } };
  /* Bug hunt 2026-11-28, finding 1.2: effects that last the whole fight (training wards, class tools) carry permanent: true and a
     player text (desc). The battle view shows no turn counter for them, the hero tab lists them with their level, the battle view names them
     at battle start. permanentEffects() is the single source for those texts. */
  const WARD_IDS = { mage: 'frostarmor', warlock: 'demonskin', druid: 'motw', priest: 'pwsward' };
  function wardEffect(cls) {
    const w = TRAINING_WARDS[cls]; if (!w) return null;
    return { id: WARD_IDS[cls], kind: w.shield ? 'shield' : 'ward', name: w.name, icon: w.icon, level: w.level,
      desc: w.armor ? '+' + Math.round(w.armor * 100) + '% брони на весь бой' : 'в начале боя щит на ' + Math.round(w.shield * 100) + '% максимума ХП' };
  }
  function toolEffects(cls, spec) {
    const t = CLASS_TOOLS[cls + ':' + spec], out = []; if (!t) return out;
    const pc = function (x) { return Math.round(x * 100) + '%'; };
    if (t.rf) out.push({ id: 'rf', kind: 'rf', name: 'Праведное неистовство', icon: '🔥', level: t.level, desc: 'угроза от урона ×1,6: враги охотнее бьют паладина' });
    if (t.reflect) out.push({ id: 'retaura', kind: 'reflect', name: 'Аура воздаяния', icon: '✨', level: t.level, desc: 'враг, ударивший паладина, получает ' + pc(t.reflect) + ' его атаки уроном Света' });
    if (t.seal) out.push({ id: 'sealright', kind: 'seal', name: 'Печать праведности', icon: '⚖️', level: t.level, desc: 'удары с шансом 30% добавляют 70% атаки уроном Света' });
    if (t.shield) out.push({ id: 'manashield', kind: 'shield', name: 'Мана-щит', icon: '🔷', level: t.level, desc: 'в начале боя щит на ' + pc(t.shield) + ' максимума ХП' });
    return out;
  }
  function permanentEffects(cls, spec, training) { if (training) { const w = wardEffect(cls); return w ? [w] : []; } return toolEffects(cls, spec); }

const pe = wardEffect(h.cls);
if (w.shield) h.effects.push({ kind: 'shield', amt: Math.round(h.maxHp * w.shield), turns: 999, src: h.id, name: w.name, icon: w.icon, permanent: true, desc: pe.desc });
else h.effects.push({ kind: 'ward', turns: 999, src: h.id, name: w.name, icon: w.icon, permanent: true, desc: pe.desc });

